{
  "correction_rules": [
    "Bias correction: Model consistently overestimates prices; reduce forecast by 1-2% for long-term (30d) horizons.",
    "Lag correction: Forecast often lags true price movements; adjust for recent sentiment shifts (e.g., +0.50) by adding 0.5–1.5% to forecast if sentiment is positive.",
    "Overshoot after spikes: After price spikes (e.g., >72), model tends to overcorrect downward; cap downward adjustments at 10% of spike magnitude.",
    "Mean reversion: If 30d forecast is >75, apply downward pressure by 1–3% to align with historical mean of 68–70.",
    "Sentiment-driven adjustment: If sentiment > 0.25, increase forecast by 0.5–1.0% to reflect bullish momentum; if sentiment < -0.25, reduce by 0.5–1.0%."
  ]
}
